```php
<?php
// ==========================================================================
// 1. CONEXÃO E CONFIGURAÇÃO
// ==========================================================================
require 'db_connect.php';

// Função auxiliar para criar a cláusula IN segura
function createInClause(string $column, array $values, &$types, array &$params): string {
    if (empty($values)) {
        return "1=1"; // Cláusula sempre verdadeira, mas segura
    }
    $placeholders = implode(',', array_fill(0, count($values), '?'));
    // Assumindo que todos são strings ('s') no seu contexto
    $types .= str_repeat('s', count($values));

    foreach ($values as $value) {
        // Garantir que o valor é tratado como string no array de parâmetros
        $params[] = (string)$value; 
    }
    return "$column IN ($placeholders)";
}

// ==========================================================================
// 2. BUSCAS INICIAIS (Para popular os dropdowns)
// ==========================================================================
$all_gres = [];
$all_escolas = [];
$all_professores = [];
$all_turmas_info = []; // Usaremos isso para armazenar resultados finais

try {
    // Buscar GREs (Lista mestre)
    $stmt_gres = $conn->prepare("SELECT DISTINCT gre FROM turmas WHERE gre LIKE 'GRE%' ORDER BY gre");
    $stmt_gres->execute();
    $res_gres = $stmt_gres->get_result();
    while ($row = $res_gres->fetch_assoc()) {
        $all_gres[] = $row;
    }
    $stmt_gres->close();

    // OBS: As buscas por escolas, professores e turmas dependem da seleção
    // Se você quiser popular todos os selects inicialmente, precisaria de
    // consultas mais complexas ou deixá-los desabilitados até o primeiro filtro.
    // Por enquanto, mantemos o comportamento onde eles só são populados após o filtro.

} catch (Exception $e) {
    die("Erro ao buscar dados iniciais: " . $e->getMessage());
}


// ==========================================================================
// 3. FUNÇÃO CENTRAL DE FILTRAGEM DE TURMAS
// ==========================================================================
function determineTurmas(mysqli $conn, array $filters): array {
    $gre = $filters['gre'] ?? [];
    $escola = $filters['escola'] ?? [];
    $professor = $filters['professor'] ?? [];
    $turma_ids = $filters['turma'] ?? [];

    $types = '';
    $params = [];
    $where_clauses = [];

    // Prioriza a seleção por ID de Turma
    if (!empty($turma_ids)) {
        $turma_clause = createInClause('id', $turma_ids, $types, $params);
        $where_clauses[] = $turma_clause;
    } else {
        // Lógica de filtragem encadeada (AND)
        if (!empty($professor)) {
            $professor_clause = createInClause('professor', $professor, $types, $params);
            $where_clauses[] = $professor_clause;
        }
        if (!empty($escola)) {
            $escola_clause = createInClause('escola', $escola, $types, $params);
            $where_clauses[] = $escola_clause;
        }
        if (!empty($gre)) {
            $gre_clause = createInClause('gre', $gre, $types, $params);
            $where_clauses[] = $gre_clause;
        }
    }

    $where = '';
    if (!empty($where_clauses)) {
        $where = 'WHERE ' . implode(' AND ', $where_clauses);
    }

    // Consulta consolidada para buscar todas as infos da turma
    $sql = "SELECT *, t.turma FROM turmas t $where";
    $stmt = $conn->prepare($sql);

    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }

    // Bind parâmetros (Isso é mais robusto, pois a função anterior só montava a string)
    if (!empty($params)) {
        // IMPORTANTE: Usar call_user_func_array ou ...$params para passar todos os argumentos de bind_param
        $stmt->bind_param($types, ...$params);
    }

    $stmt->execute();
    $result = $stmt->get_result();
    $stmt->close();

    $turma_info = [];
    while ($row = $result->fetch_assoc()) {
        $turma_info[] = $row;
    }
    return $turma_info;
}

// ==========================================================================
// 4. EXECUÇÃO DO FILTRO PRINCIPAL
// ==========================================================================
$current_turma_info = [];
$filters = [
    'gre' => $_GET['gre'] ?? [],
    'escola' => $_GET['escola'] ?? [],
    'professor' => $_GET['professor'] ?? [],
    'turma' => $_GET['turma'] ?? []
];

// Executa a função central se houver qualquer filtro ativo
